// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(address actor, uint256 extra) public {
        vm.assume(actor != address(0) && actor != address(c));
        extra = bound(extra, 0, 100 ether);
        uint256 value = 1 ether + extra;
        vm.deal(actor, value);
        vm.prank(actor);
        c.Deposit{value: value}();
        assertTrue(c.balances(actor) == value, "deposit of value >= MinDeposit must be credited");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint amount) public {
        require(amount >= 1 ether);
        require(address(this).balance >= amount);
        uint before = c.balances(address(this));
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == before + amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint amt1, uint amt2) public {
        require(amt1 >= c.MinDeposit());
        require(amt2 >= c.MinDeposit());
        require(address(this).balance >= amt1 + amt2);
        c.Deposit{value: amt1}();
        c.Deposit{value: amt2}();
        assert(c.balances(address(this)) == amt1 + amt2);
    }
    receive() external payable {}
    fallback() external payable {}
}
